// Struct Tag and Typedef Share the Name 'Node'
typedef struct Node {
    int value;
    // CRITICAL: Must use the struct Tag for self-reference
    struct Node *next;
} Node; // 'Node' is the new Type Name

// Declaration using Typedef (Preferred syntax)
Node n1;

// Declaration using Struct Tag (Requires 'struct' keyword)
struct Node n2;

// If only the Tag existed:
struct OnlyTag { int x; };
struct OnlyTag t3; // 'OnlyTag t3;' would fail.
